import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {hash,json} from './seal-simple-website-successor.mjs';
const sourceFile='F:/VisibleMedicine/staging/20261025-canonical-csp-website/SOURCE_CANDIDATE.json';assert.equal(hash(sourceFile),'b21223ba0c84a9cf6b56e9a1956a2c13fad03f66353197acde115bc1e0eb0c90');
const source=json(sourceFile),worker='F:/VisibleMedicine/staging/20261025-studio-ui-epoch-role-proposal',patch=json(worker+'/PATCHSET.json'),dir='F:/VisibleMedicine/staging/20261025-studio-ui-epoch-main-patch';assert(!fs.existsSync(dir));
const files=[];fs.mkdirSync(dir);
for(const r of patch.install){const row=source.sourceRows.find(v=>v.path===r.destination);assert(row);assert.equal(row.sha256,r.expectedOriginalSha256);assert.equal(hash(worker+'/'+r.source),r.replacementSha256);const to=dir+'/'+r.destination;fs.mkdirSync(path.dirname(to),{recursive:true});fs.copyFileSync(worker+'/'+r.source,to,fs.constants.COPYFILE_EXCL);files.push({path:r.destination,beforeSha256:r.expectedOriginalSha256,afterSha256:r.replacementSha256});}
const extra=patch.blockingIntegrationPrerequisite,p=extra.path;assert.equal(hash(source.website+'/'+p),extra.expectedOriginalSha256);
const before=fs.readFileSync(source.website+'/'+p,'utf8');assert.equal(before.split(extra.exactOldWitnessSha256).length,2);const after=before.replace(extra.exactOldWitnessSha256,extra.exactReplacementWitnessSha256);assert.equal(after.split(extra.exactReplacementWitnessSha256).length,2);assert.equal(after.replace(extra.exactReplacementWitnessSha256,extra.exactOldWitnessSha256),before);
const to=dir+'/'+p;fs.mkdirSync(path.dirname(to),{recursive:true});fs.writeFileSync(to,after,{flag:'wx'});assert.equal(hash(to),extra.resultingAdapterSha256IfOnlyThatLiteralChanges);
files.push({path:p,beforeSha256:extra.expectedOriginalSha256,afterSha256:hash(to)});assert.equal(files.length,4);
fs.writeFileSync(dir+'/PATCHSET.json',JSON.stringify({schema:'vm-main-studio-ui-atomic-patch/1',at:new Date().toISOString(),base:{path:sourceFile,sha256:hash(sourceFile)},worker:{path:worker+'/PATCHSET.json',sha256:hash(worker+'/PATCHSET.json')},installableFiles:files,mainOwnedEdit:'Exactly one recipe witness SHA literal; full inverse restores every original adapter registration/assertion byte. Three worker files unchanged.',actualRuntimePending:true},null,2)+'\n',{flag:'wx'});
